/*
 * chiron.js — precomputed Chiron ecliptic longitude (tropical, of date),
 * generated with Swiss Ephemeris (seas_18). Range 1900-2100, 4-day step,
 * 3-byte fixed point. Linear interpolation is accurate to ~0.25 arc-minutes.
 * License note: derived from the Swiss Ephemeris free edition (AGPL).
 */
(function(root){
  "use strict";
  var JD_START=2415020.5, STEP=4, N=18264;
  var B64="";
  var BYTES=null;
  function bytes(){ if(BYTES) return BYTES; if(typeof atob==="function"){var bin=atob(B64);BYTES=new Uint8Array(bin.length);for(var i=0;i<bin.length;i++)BYTES[i]=bin.charCodeAt(i);}else{BYTES=Uint8Array.from(Buffer.from(B64,"base64"));} return BYTES; }
  function sample(i){ var b=bytes(); var o=i*3; var v=(b[o]<<16)|(b[o+1]<<8)|b[o+2]; return v/16777216*360; }
  // Chiron tropical longitude at a given UT Julian Day.
  function longitude(jd){ if(jd<=JD_START) return sample(0); if(jd>=JD_START+(N-1)*STEP) return sample(N-1); var x=(jd-JD_START)/STEP; var i=Math.floor(x); var f=x-i; var l0=sample(i), l1=sample(i+1); var d=l1-l0; if(d>180)d-=360; if(d<-180)d+=360; return ((l0+d*f)%360+360)%360; }
  root.ChironTable={ longitude:longitude, JD_START:JD_START, JD_END:JD_START+(N-1)*STEP };
  if(typeof module!=="undefined"&&module.exports) module.exports=root.ChironTable;
})(typeof globalThis!=="undefined"?globalThis:this);
